   126  #define BITS_FLUSH(m_pu4_buf, m_u4_bit_ofst, m_u4_cur_word, \
   127                      m_u4_nxt_word, m_cnt)                   \
   128  {                                                           \
   129      UWORD32 temp;                                           \
   130                                                              \
   131      m_u4_bit_ofst += m_cnt;                                 \
   132      if( m_u4_bit_ofst >=   WORD_SIZE )                      \
